<div class="page-head"><h1>Daftar Alat</h1><p>Daftar alat yang tersedia untuk sistem peminjaman</p></div><?php if($m=flash('success')):?><div class="alert success"><?=e($m)?></div><?php endif;?><?php if($m=flash('error')):?><div class="alert"><?=e($m)?></div><?php endif;?><div class="card"><form class="searchbar" method="get"><input type="hidden" name="route" value="alat"><input class="input" name="q" value="<?=e($_GET['q']??'')?>" placeholder="Cari nama/kode alat"><button class="btn btn-primary">Cari</button><?php if(has_role('admin')):?><a class="btn" href="<?=base_url('alat/create')?>">+ Input Alat</a><?php endif;?></form><div class="table-wrap"><table class="table"><thead><tr><th>NO</th><th>KODE</th><th>NAMA ALAT</th><th>KATEGORI</th><th>TERSEDIA</th><th>KONDISI</th><th>LOKASI</th><th>STATUS</th><th>AKSI</th></tr></thead><tbody><?php foreach($alat as $i=>$a):?><tr><td><?=$i+1?></td><td><?=e($a['kode_alat'])?></td><td><?=e($a['nama_alat'])?></td><td><?=e($a['nama_kategori'])?></td><td><?=e($a['jumlah_tersedia'])?> / <?=e($a['jumlah'])?></td><td><?=e($a['kondisi'])?></td><td><?=e($a['lokasi'])?></td><td><span class="badge <?=$a['jumlah_tersedia']>0?'badge-success':'badge-danger'?>"><?=e($a['status'])?></span></td><td class="actions"><a class="btn btn-sm" href="<?=base_url('alat/detail/'.$a['id'])?>">◉</a><?php if(has_role('peminjam')&&$a['jumlah_tersedia']>0&&$a['status']==='Tersedia'):?><a class="btn btn-sm btn-primary" href="<?=base_url('peminjaman/create?alat_id='.$a['id'])?>">Pinjam</a><?php endif;?><?php if(has_role('admin')):?><a class="btn btn-sm" href="<?=base_url('alat/edit/'.$a['id'])?>">✎</a><form method="post" action="<?=e(base_url('alat/delete/'.$a['id']))?>" class="inline-action" onsubmit="return confirm('Hapus alat?')"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><button class="btn btn-sm btn-danger" type="submit">▥</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div>
